int setup_efi_state(struct boot_params *params, unsigned long params_load_addr, unsigned int efi_map_offset, unsigned int efi_map_sz, unsigned int efi_setup_data_offset) {
    if (!params || efi_map_sz == 0 || efi_map_offset + efi_map_sz > params_load_addr + sizeof(*params)) {
        return 0;
    }

    if (!is_1_1_mapping_enabled()) {
        return 0;
    }

    if (efi_map_sz > sizeof(params->efi_info)) {
        efi_map_sz = sizeof(params->efi_info);
    }

    memcpy(&params->efi_info, (void *)params_load_addr + efi_map_offset, efi_map_sz);

    if (efi_setup_data_offset != 0) {
        if (efi_setup_data_offset > params_load_addr + sizeof(*params)) {
            return 0;
        }

        params->efi_setup_data = (void *)((unsigned long)params + efi_setup_data_offset);
    }

    return 0;
}
